python3 -c "
import json
with open('/app/resources/treasury_bulletin_2025_06.json', 'r') as f:
    data = json.load(f)

# Search for Japanese yen in the data
def search_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            search_dict(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            search_dict(item, f'{path}[{i}]')
    else:
        if 'Japanese' in str(d) or 'yen' in str(d).lower():
            print(f'{path}: {d}')

search_dict(data)
